import{_ as t,o,c as d,a3 as r}from"./chunks/framework.CWCEHGF4.js";const a="/MeshPaintingDoc/color-picker/01-default-widget-asset.png",i="/MeshPaintingDoc/color-picker/04-parent-class.png",c="/MeshPaintingDoc/color-picker/02-duplicate-widget.png",n="/MeshPaintingDoc/color-picker/03-custom-widget-copy.png",l="/MeshPaintingDoc/color-picker/07-controller-widget-class.png",s="/MeshPaintingDoc/color-picker/05-designer-overview.png",h="/MeshPaintingDoc/color-picker/06-widget-hierarchy.png",k=JSON.parse('{"title":"WBP_RuntimeColorPicker","description":"","frontmatter":{},"headers":[],"relativePath":"systems/color-picker.md","filePath":"systems/color-picker.md","lastUpdated":1784646593000}'),p={name:"systems/color-picker.md"};function u(g,e,m,C,b,w){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="wbp-runtimecolorpicker" tabindex="-1">WBP_RuntimeColorPicker <a class="header-anchor" href="#wbp-runtimecolorpicker" aria-label="Permalink to &quot;WBP_RuntimeColorPicker&quot;">​</a></h1><p><code>WBP_RuntimeColorPicker</code> is the default runtime color picker widget included with the plugin.</p><p>It is designed to work directly with <code>PaintingModeControllerComponent</code>. When paint mode opens, the controller creates the widget, adds it to the viewport, and passes itself to the widget through the runtime paint target interface.</p><p><img src="'+a+'" alt="Default WBP_RuntimeColorPicker asset"></p><h2 id="parent-class" tabindex="-1">Parent Class <a class="header-anchor" href="#parent-class" aria-label="Permalink to &quot;Parent Class&quot;">​</a></h2><p>The parent class is <code>Color Picker Panel Widget</code>, implemented in C++ as <code>UColorPickerPanelWidget</code>.</p><p><img src="'+i+'" alt="Color Picker Panel Widget parent class"></p><p>Keep this parent class when making custom versions. The parent class owns the actual color picker logic:</p><ul><li>Current and previous color state</li><li>RGB, HSV, and hex synchronization</li><li>Brush size, metallic, and roughness values</li><li>Eraser state</li><li>Eyedropper mode</li><li>Recent color history</li><li>Tool strip behavior</li><li>Paint target integration</li><li>Blueprint events</li></ul><h2 id="recommended-custom-workflow" tabindex="-1">Recommended Custom Workflow <a class="header-anchor" href="#recommended-custom-workflow" aria-label="Permalink to &quot;Recommended Custom Workflow&quot;">​</a></h2><p>Do not build a custom color picker from an empty widget unless you are intentionally replacing the whole UI system.</p><p>The recommended workflow is:</p><ol><li>Find <code>WBP_RuntimeColorPicker</code>.</li><li>Duplicate it.</li><li>Rename the duplicate, for example <code>WBP_MyRuntimeColorPicker</code>.</li><li>Keep the parent class as <code>Color Picker Panel Widget</code>.</li><li>Change the layout, colors, padding, icons, fonts, and visual style.</li><li>Keep the bound widget names unless you intentionally remove that feature.</li><li>Assign the duplicated widget to <code>PaintingModeControllerComponent &gt; Widget &gt; Color Picker Widget Class</code>.</li></ol><p><img src="'+c+'" alt="Duplicate WBP_RuntimeColorPicker"></p><p><img src="'+n+'" alt="Custom widget copy next to the default widget"></p><p><img src="'+l+'" alt="Assign custom color picker widget class"></p><p>This keeps the C++ event binding, brush setting sync, eyedropper, eraser, and recent color behavior intact.</p><h2 id="designer-overview" tabindex="-1">Designer Overview <a class="header-anchor" href="#designer-overview" aria-label="Permalink to &quot;Designer Overview&quot;">​</a></h2><p>You can freely restyle the duplicate widget in the Designer.</p><p><img src="'+s+'" alt="Color picker designer overview"></p><p>Safe changes:</p><ul><li>Move panels around.</li><li>Change colors, backgrounds, borders, and padding.</li><li>Resize rows and previews.</li><li>Replace icons and styling.</li><li>Hide optional sections you do not need.</li></ul><p>Risky changes:</p><ul><li>Renaming bound widgets.</li><li>Deleting a bound widget but expecting its feature to keep working.</li><li>Changing the parent class.</li><li>Replacing plugin child widgets with normal UMG widgets that do not expose the expected events.</li></ul><h2 id="important-widget-names" tabindex="-1">Important Widget Names <a class="header-anchor" href="#important-widget-names" aria-label="Permalink to &quot;Important Widget Names&quot;">​</a></h2><p><code>UColorPickerPanelWidget</code> uses optional widget binding. That means the widget can still build a native fallback layout if nothing is provided, but a custom Blueprint should keep these names when it wants the built-in behavior.</p><p><img src="'+h+`" alt="Color picker widget hierarchy"></p><table tabindex="0"><thead><tr><th>Widget Name</th><th>Expected Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>RootBorder</code></td><td><code>Border</code></td><td>Main panel area, padding, and cursor-over-UI detection.</td></tr><tr><td><code>ColorWheel</code></td><td><code>Color Wheel Widget</code></td><td>Hue/saturation or spectrum color selection.</td></tr><tr><td><code>SaturationBar</code></td><td><code>Vertical Color Bar Widget</code></td><td>Saturation adjustment in wheel mode.</td></tr><tr><td><code>ValueBar</code></td><td><code>Vertical Color Bar Widget</code></td><td>Value/brightness adjustment.</td></tr><tr><td><code>CurrentPreview</code></td><td><code>Color Preview Widget</code></td><td>Shows the current color.</td></tr><tr><td><code>PreviousPreview</code></td><td><code>Color Preview Widget</code></td><td>Shows and restores the previous color when clicked.</td></tr><tr><td><code>ToolStrip</code></td><td><code>Color Picker Tool Strip Widget</code></td><td>Color mode, eyedropper, palette visibility, and eraser buttons.</td></tr><tr><td><code>SrgbPreviewOption</code></td><td><code>Color Option Row Widget</code></td><td>Toggles sRGB preview display.</td></tr><tr><td><code>HexInput</code></td><td><code>Hex Color Input Widget</code></td><td>Hex color input and validation.</td></tr><tr><td><code>HistoryBar</code></td><td><code>Color History Bar Widget</code></td><td>Recent colors and palette colors.</td></tr><tr><td><code>RedRow</code></td><td><code>Color Channel Row Widget</code></td><td>Red channel.</td></tr><tr><td><code>GreenRow</code></td><td><code>Color Channel Row Widget</code></td><td>Green channel.</td></tr><tr><td><code>BlueRow</code></td><td><code>Color Channel Row Widget</code></td><td>Blue channel.</td></tr><tr><td><code>HueRow</code></td><td><code>Color Channel Row Widget</code></td><td>Hue channel.</td></tr><tr><td><code>SaturationRow</code></td><td><code>Color Channel Row Widget</code></td><td>HSV saturation channel.</td></tr><tr><td><code>ValueRow</code></td><td><code>Color Channel Row Widget</code></td><td>HSV value channel.</td></tr><tr><td><code>BrushSizeRow</code></td><td><code>Color Channel Row Widget</code></td><td>Normalized brush size slider.</td></tr><tr><td><code>MetallicRow</code></td><td><code>Color Channel Row Widget</code></td><td>Brush metallic value.</td></tr><tr><td><code>RoughnessRow</code></td><td><code>Color Channel Row Widget</code></td><td>Brush roughness value.</td></tr><tr><td><code>PaintScalarRowsStack</code></td><td><code>Vertical Box</code></td><td>Container used for brush size, metallic, and roughness rows.</td></tr></tbody></table><p>Optional legacy names such as <code>PaletteGrid</code>, <code>RecentColorsArea</code>, <code>ToolRow</code>, and <code>EyedropperButton</code> may still be present in older layouts, but the current default workflow uses <code>ToolStrip</code> and <code>HistoryBar</code>.</p><h2 id="how-it-connects-to-painting" tabindex="-1">How It Connects To Painting <a class="header-anchor" href="#how-it-connects-to-painting" aria-label="Permalink to &quot;How It Connects To Painting&quot;">​</a></h2><p><code>PaintingModeControllerComponent</code> controls widget creation.</p><p>When <code>Auto Create Color Picker Widget</code> is enabled, the controller:</p><ul><li>Creates the widget class stored in <code>Color Picker Widget Class</code>.</li><li>Adds it to the viewport using <code>Color Picker Widget ZOrder</code>.</li><li>Calls <code>SetPaintTarget(this)</code> on the widget.</li><li>Keeps brush size synchronized through <code>OnBrushSizeChanged</code>.</li><li>Calls <code>NotifyPaintApplied</code> after successful paint so recent colors can be updated.</li></ul><p>The widget then pushes brush settings back through <code>ApplyBrushSettingsToPaintTarget</code> when <code>Push Settings To Paint Target</code> is enabled.</p><h2 id="main-settings" tabindex="-1">Main Settings <a class="header-anchor" href="#main-settings" aria-label="Permalink to &quot;Main Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>CurrentColor</code></td><td>Current paint color.</td></tr><tr><td><code>PreviousColor</code></td><td>Previous color used by the previous-preview button.</td></tr><tr><td><code>BrushSize</code></td><td>Normalized UI brush size from <code>0.01</code> to <code>1.0</code>.</td></tr><tr><td><code>Metallic</code></td><td>Current brush metallic value.</td></tr><tr><td><code>Roughness</code></td><td>Current brush roughness value.</td></tr><tr><td><code>Push Settings To Paint Target</code></td><td>Automatically applies changed brush settings to the assigned paint target.</td></tr><tr><td><code>Palette Data Asset</code></td><td>Optional default palette color source.</td></tr><tr><td><code>Palette Save Slot Name</code></td><td>Storage name used by the palette storage object.</td></tr><tr><td><code>Eyedropper Trace Channel</code></td><td>Collision channel used by the eyedropper trace.</td></tr><tr><td><code>Eyedropper Trace Complex</code></td><td>Enables complex tracing for eyedropper hit resolution.</td></tr><tr><td><code>Build Native Layout If Missing</code></td><td>Allows the C++ parent class to build a fallback UI if no designer tree exists.</td></tr><tr><td><code>Recent Colors Expanded</code></td><td>Shows or hides the recent/history color area.</td></tr><tr><td><code>Panel Padding</code></td><td>Padding applied to <code>RootBorder</code>.</td></tr></tbody></table><h2 id="brush-size-sync" tabindex="-1">Brush Size Sync <a class="header-anchor" href="#brush-size-sync" aria-label="Permalink to &quot;Brush Size Sync&quot;">​</a></h2><p>The color picker stores brush size as a normalized UI value.</p><p>The actual paint brush size comes from:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Normalized Brush Size * PaintingModeControllerComponent.MaxBrushSize</span></span></code></pre></div><p>When the controller brush size changes from input, the widget receives <code>OnBrushSizeChanged</code> and updates <code>BrushSizeRow</code> without creating a new paint history entry.</p><h2 id="recent-color-history" tabindex="-1">Recent Color History <a class="header-anchor" href="#recent-color-history" aria-label="Permalink to &quot;Recent Color History&quot;">​</a></h2><p>Recent colors are added after successful painting.</p><p>Changing a slider, selecting from the palette, or typing a hex value does not add a color to recent history by itself. This keeps the history focused on colors that were actually used on a mesh.</p><p>Eraser mode does not add colors to history.</p><h2 id="eyedropper" tabindex="-1">Eyedropper <a class="header-anchor" href="#eyedropper" aria-label="Permalink to &quot;Eyedropper&quot;">​</a></h2><p>The eyedropper can sample both painted targets and visible viewport color.</p><p>Flow:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Begin eyedropper</span></span>
<span class="line"><span>-&gt; Left mouse confirms</span></span>
<span class="line"><span>-&gt; Trace under cursor</span></span>
<span class="line"><span>-&gt; Try paint target color sample</span></span>
<span class="line"><span>-&gt; Fallback to viewport pixel sample</span></span>
<span class="line"><span>-&gt; Update current color</span></span>
<span class="line"><span>-&gt; Commit color</span></span>
<span class="line"><span>-&gt; Exit eyedropper</span></span></code></pre></div><p>Right mouse or Escape cancels eyedropper mode.</p><h2 id="panel-events" tabindex="-1">Panel Events <a class="header-anchor" href="#panel-events" aria-label="Permalink to &quot;Panel Events&quot;">​</a></h2><p>These are the main events exposed by <code>Color Picker Panel Widget</code>.</p><table tabindex="0"><thead><tr><th>Event</th><th>Data</th><th>When It Fires</th></tr></thead><tbody><tr><td><code>OnColorChanged</code></td><td><code>Color</code></td><td>Current color changes from wheel, bars, channel rows, hex input, palette, previous preview, or eyedropper.</td></tr><tr><td><code>OnColorCommitted</code></td><td><code>Color</code></td><td>A color interaction is committed, such as finishing a drag, confirming hex, selecting palette color, or sampling with eyedropper.</td></tr><tr><td><code>OnOptionChanged</code></td><td><code>OptionId</code>, <code>bIsEnabled</code></td><td>A boolean option changes. The built-in option id is <code>sRGBPreview</code>.</td></tr><tr><td><code>OnScalarChanged</code></td><td><code>ScalarId</code>, <code>Value</code></td><td>Brush size, metallic, or roughness changes.</td></tr><tr><td><code>OnScalarCommitted</code></td><td><code>ScalarId</code>, <code>Value</code></td><td>A scalar row finishes editing.</td></tr><tr><td><code>OnBrushSettingsChanged</code></td><td><code>Settings</code></td><td>Color, brush size, metallic, roughness, or eraser state changes and a full brush settings struct is rebuilt.</td></tr><tr><td><code>OnToolClicked</code></td><td><code>ToolId</code></td><td>A tool strip button is clicked.</td></tr><tr><td><code>OnToolToggled</code></td><td><code>ToolId</code>, <code>bIsChecked</code></td><td>A toggle-like tool changes state.</td></tr><tr><td><code>OnPaletteColorSelected</code></td><td><code>Color</code>, <code>ColorIndex</code></td><td>A color is selected from the palette/history area.</td></tr><tr><td><code>OnEyedropperRequested</code></td><td>None</td><td>Eyedropper mode starts.</td></tr><tr><td><code>OnEyedropperActiveChanged</code></td><td><code>bIsActive</code></td><td>Eyedropper starts or ends.</td></tr><tr><td><code>OnColorSampled</code></td><td><code>SampleResult</code></td><td>Eyedropper successfully samples a color.</td></tr></tbody></table><p>Common ids:</p><table tabindex="0"><thead><tr><th>Id Type</th><th>Values</th></tr></thead><tbody><tr><td>Color channel ids</td><td><code>R</code>, <code>G</code>, <code>B</code>, <code>H</code>, <code>S</code>, <code>V</code></td></tr><tr><td>Scalar ids</td><td><code>BrushSize</code>, <code>Metallic</code>, <code>Roughness</code></td></tr><tr><td>Option ids</td><td><code>sRGBPreview</code></td></tr><tr><td>Tool ids</td><td><code>ColorMode</code>, <code>Eyedropper</code>, <code>Palette</code>, <code>Eraser</code></td></tr></tbody></table><h2 id="child-widget-events" tabindex="-1">Child Widget Events <a class="header-anchor" href="#child-widget-events" aria-label="Permalink to &quot;Child Widget Events&quot;">​</a></h2><p>The panel consumes these child widget events internally, but they are also useful when you build advanced custom layouts.</p><h3 id="color-wheel-widget" tabindex="-1">Color Wheel Widget <a class="header-anchor" href="#color-wheel-widget" aria-label="Permalink to &quot;Color Wheel Widget&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>Data</th><th>Use</th></tr></thead><tbody><tr><td><code>OnHueSaturationChanged</code></td><td><code>Hue</code>, <code>Saturation</code></td><td>React to hue/saturation movement.</td></tr><tr><td><code>OnHSVChanged</code></td><td><code>Hue</code>, <code>Saturation</code>, <code>Value</code></td><td>React to full HSV changes.</td></tr><tr><td><code>OnInteractionStarted</code></td><td>None</td><td>Detect the start of a wheel/spectrum drag.</td></tr><tr><td><code>OnHueSaturationCommitted</code></td><td><code>Hue</code>, <code>Saturation</code></td><td>React after wheel interaction finishes.</td></tr><tr><td><code>OnHSVCommitted</code></td><td><code>Hue</code>, <code>Saturation</code>, <code>Value</code></td><td>Commit full HSV after interaction finishes.</td></tr></tbody></table><h3 id="color-channel-row-widget" tabindex="-1">Color Channel Row Widget <a class="header-anchor" href="#color-channel-row-widget" aria-label="Permalink to &quot;Color Channel Row Widget&quot;">​</a></h3><p>Used by <code>RedRow</code>, <code>GreenRow</code>, <code>BlueRow</code>, <code>HueRow</code>, <code>SaturationRow</code>, <code>ValueRow</code>, <code>BrushSizeRow</code>, <code>MetallicRow</code>, and <code>RoughnessRow</code>.</p><table tabindex="0"><thead><tr><th>Event</th><th>Data</th><th>Use</th></tr></thead><tbody><tr><td><code>OnValueChanged</code></td><td><code>ChannelId</code>, <code>Value</code></td><td>A slider/spinbox value changes.</td></tr><tr><td><code>OnInteractionStarted</code></td><td><code>ChannelId</code>, <code>InitialValue</code></td><td>The user starts editing this row.</td></tr><tr><td><code>OnValueCommitted</code></td><td><code>ChannelId</code>, <code>Value</code></td><td>The user commits the row value.</td></tr></tbody></table><h3 id="color-bar-widgets" tabindex="-1">Color Bar Widgets <a class="header-anchor" href="#color-bar-widgets" aria-label="Permalink to &quot;Color Bar Widgets&quot;">​</a></h3><p><code>VerticalColorBarWidget</code> is used by saturation/value bars. <code>HorizontalColorBarWidget</code> is available for custom layouts.</p><table tabindex="0"><thead><tr><th>Event</th><th>Data</th><th>Use</th></tr></thead><tbody><tr><td><code>OnValueChanged</code></td><td><code>Value</code></td><td>The bar value changes.</td></tr><tr><td><code>OnInteractionStarted</code></td><td>None</td><td>The user starts dragging the bar.</td></tr><tr><td><code>OnValueCommitted</code></td><td><code>Value</code></td><td>The user finishes dragging the bar.</td></tr></tbody></table><h3 id="hex-color-input-widget" tabindex="-1">Hex Color Input Widget <a class="header-anchor" href="#hex-color-input-widget" aria-label="Permalink to &quot;Hex Color Input Widget&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>Data</th><th>Use</th></tr></thead><tbody><tr><td><code>OnHexCommitted</code></td><td><code>HexText</code>, <code>Color</code>, <code>bIsValid</code>, <code>bHasAlpha</code></td><td>A hex value is committed. Invalid values should be ignored.</td></tr><tr><td><code>OnValidityChanged</code></td><td><code>bIsValid</code></td><td>The text becomes valid or invalid while editing.</td></tr></tbody></table><h3 id="tool-widgets" tabindex="-1">Tool Widgets <a class="header-anchor" href="#tool-widgets" aria-label="Permalink to &quot;Tool Widgets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Widget</th><th>Event</th><th>Data</th><th>Use</th></tr></thead><tbody><tr><td><code>ColorPickerToolStripWidget</code></td><td><code>OnButtonClicked</code></td><td><code>ToolId</code></td><td>Built-in tool strip button was clicked.</td></tr><tr><td><code>ColorToolButtonWidget</code></td><td><code>OnClicked</code></td><td><code>ToolId</code></td><td>Custom standalone tool button clicked.</td></tr><tr><td><code>ColorToolButtonWidget</code></td><td><code>OnToggled</code></td><td><code>ToolId</code>, <code>bIsChecked</code></td><td>Custom standalone tool toggle changed.</td></tr><tr><td><code>ColorEyedropperButtonWidget</code></td><td><code>OnClicked</code></td><td>None</td><td>Legacy/custom eyedropper button clicked.</td></tr></tbody></table><h3 id="palette-and-preview-widgets" tabindex="-1">Palette and Preview Widgets <a class="header-anchor" href="#palette-and-preview-widgets" aria-label="Permalink to &quot;Palette and Preview Widgets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Widget</th><th>Event</th><th>Data</th><th>Use</th></tr></thead><tbody><tr><td><code>ColorHistoryBarWidget</code></td><td><code>OnColorSelected</code></td><td><code>Color</code>, <code>ColorIndex</code></td><td>A recent/history color was selected.</td></tr><tr><td><code>ColorPaletteGridWidget</code></td><td><code>OnColorSelected</code></td><td><code>Color</code>, <code>ColorIndex</code></td><td>A palette color was selected.</td></tr><tr><td><code>ColorSwatchWidget</code></td><td><code>OnSwatchSelected</code></td><td><code>Color</code>, <code>SwatchIndex</code></td><td>A single swatch was clicked.</td></tr><tr><td><code>ColorPreviewWidget</code></td><td><code>OnClicked</code></td><td><code>Color</code></td><td>A clickable color preview was clicked.</td></tr><tr><td><code>ColorOptionRowWidget</code></td><td><code>OnCheckStateChanged</code></td><td><code>OptionId</code>, <code>bIsChecked</code></td><td>A boolean option row changed.</td></tr></tbody></table><h2 id="customization-rules" tabindex="-1">Customization Rules <a class="header-anchor" href="#customization-rules" aria-label="Permalink to &quot;Customization Rules&quot;">​</a></h2><p>Follow these rules when making a custom color picker:</p><ul><li>Duplicate <code>WBP_RuntimeColorPicker</code>.</li><li>Keep parent class as <code>Color Picker Panel Widget</code>.</li><li>Assign the duplicate in <code>PaintingModeControllerComponent &gt; Color Picker Widget Class</code>.</li><li>Keep widget names if you want the built-in binding to keep working.</li><li>Keep plugin widget classes for color controls. For example, keep <code>ColorWheel</code> as <code>Color Wheel Widget</code>, not a normal image.</li><li>Do not bind expensive Blueprint logic to high-frequency events such as <code>OnColorChanged</code>, <code>OnScalarChanged</code>, or row <code>OnValueChanged</code>.</li><li>Use commit events when you only need final user input.</li><li>Keep <code>RootBorder</code> if you want painting to stop while the cursor is over the color picker UI.</li></ul><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Creating a new blank widget instead of duplicating <code>WBP_RuntimeColorPicker</code>.</li><li>Changing the parent class away from <code>Color Picker Panel Widget</code>.</li><li>Renaming <code>ColorWheel</code>, <code>ToolStrip</code>, <code>HistoryBar</code>, or channel rows and expecting them to keep syncing.</li><li>Replacing plugin child widgets with standard UMG widgets that do not expose the same events.</li><li>Binding save/history logic to color changes instead of paint success.</li><li>Removing <code>RootBorder</code>, causing cursor-over-panel detection to become unreliable.</li><li>Forgetting to assign the custom widget class on <code>PaintingModeControllerComponent</code>.</li></ul>`,76)])])}const P=t(p,[["render",u]]);export{k as __pageData,P as default};
